    vmax = fmaxf(vmax, sh[ty + 3][tx]);
    vmax = fmaxf(vmax, sh[ty + 3][tx + 1]);
    vmax = fmaxf(vmax, sh[ty + 3][tx + 2]);
    vmax = fmaxf(vmax, sh[ty + 3][tx + 3]);

